-- Register Voldemar Ulmer and Hans von Manteuffel-Szoege; move the 20 borderland people's long bios into their
-- detail sections (which still held the first short bios) and give the cards two-sentence bios.
-- Source: docs/commulingo-civil-war-restructure/people-add-2026-09-05.json. Run as postgres.
BEGIN;
INSERT INTO commulingo_people (id, group_id, sort_order, initial, cyrillic, years_label, birth_year, death_year, name_ko, name_en, given_name_ko, given_name_en, family_name_ko, family_name_en, epithet_ko, epithet_en, bio_ko, bio_en, fate_kind, fate_label_ko, fate_label_en, citizenship_code, citizenship_label_ko, citizenship_label_en, origin_code, origin_label_ko, origin_label_en) SELECT 'voldemar-ulmer', 'stalin-era', COALESCE(MAX(sort_order),0)+1, '', $q$Вольдемар Августович Ульмер$q$, '1896–1945', 1896, 1945, $q$볼데마르 울메르$q$, $q$Voldemar Ulmer$q$, $q$볼데마르$q$, $q$Voldemar$q$, $q$울메르$q$, $q$Ulmer$q$, $q$대숙청 작전명령마다 「확인함」 서명을 남긴 국가보안총국 작전서기$q$, $q$Operational secretary of the GUGB whose 'certified' signature closes the Great Terror's operational orders$q$, $q$국경수비대 출신의 NKVD 여단장으로 1937년 4월부터 1938년 9월까지 국가보안총국 작전서기를 맡아 제00447호를 비롯한 예조프의 대숙청 작전명령 사본에 인증 서명을 했다. 프리놉스키의 심복으로 베리야 아래에서 한 달 비서실장을 지낸 뒤 1939년 체포되어 15년형을 받고 1945년 크라스노야르스크의 수용소에서 죽었다.$q$, $q$An NKVD brigade commander from the border troops, he served as operational secretary of the Main Directorate of State Security from April 1937 to September 1938 and certified the copies of Yezhov's Great Terror operational orders, including No. 00447. A protégé of Frinovsky, he briefly headed Beria's secretariat, was arrested in 1939, sentenced to fifteen years and died in a Krasnoyarsk camp in 1945.$q$, 'natural', $q$1945년 크라스노야르스크 수용소에서 사망$q$, $q$Died in a Krasnoyarsk camp in 1945$q$, 'soviet', $q$소련$q$, $q$Soviet Union$q$, 'estonia', $q$에스토니아 레발 출생(스웨덴계)$q$, $q$Born in Reval, Estonia (Swedish family)$q$ FROM commulingo_people WHERE group_id='stalin-era' ON CONFLICT (id) DO NOTHING;
INSERT INTO commulingo_person_sections (person_id, slug, sort_order, heading_ko, heading_en, body_ko, body_en, sources) VALUES ('voldemar-ulmer', 'great-terror', 0, $q$명령서 끝의 이름: 작전서기 울메르$q$, $q$The name at the foot of the orders: operational secretary Ulmer$q$, $q$볼데마르 요한네스 아우구스토비치 울메르는 1896년 12월 20일 에스틀란트의 레발(탈린)에서 스웨덴계 노동자 가정에 태어났다. 모스크바의 4년제 시립학교를 마치고 1916년 제4키예프 준위학교를 나와 1차 대전에 참전했고, 1914년부터 볼셰비키 당원이었다. 1921년부터 체카와 OGPU의 국경수비대에서 지휘와 교육 직책을 거쳐 1928년 프룬제 군사아카데미를 졸업했으며, 1934년 7월 국경수비 작전부장이 되었다. 1935년 12월 여단장 계급을 받았다.

1937년 4월 16일 그는 예조프의 내무인민위원부에서 국가보안총국 작전서기가 되었다. 이 자리는 총국의 명령과 지시가 각 지방 기관으로 나가는 마지막 관문이었다. 1937년 7월 30일의 작전명령 제00447호를 비롯해 대숙청의 대량 작전을 지시한 예조프의 명령 사본 끝에는 「확인함: 소련 내무인민위원부 국가보안총국 작전서기 여단장 울메르」라는 인증이 붙어 있다. 이 사이트의 「NKVD 작전명령」 문서와 1937년 문서집에 그의 이름이 거듭 나오는 이유다. 그는 명령을 만든 사람이 아니라 명령이 진본임을 보증한 사람이었고, 바로 그 서명 때문에 대숙청의 문서 기록에서 가장 자주 마주치는 이름 가운데 하나가 되었다.

프리놉스키의 심복으로 알려진 그는 1938년 9월 8일 새 제1부위원 베리야의 비서실장이 되었다. 나우모프의 연구가 전하듯 베리야는 그루지야에서 데려온 부하가 몇 명뿐이었던 첫 달 동안 그를 어쩔 수 없이 곁에 두었지만 신뢰하지 않았고, 곧 메르쿨로프로 바꾸었다. 11월 그는 호송부대 총국 부장 직무대리로 밀려났다. 1939년 4월 21일 체포되어 1940년 2월 군사법원에서 「예조프·프리놉스키·예브도키모프 음모 테러 조직」 가담 혐의로 15년 강제노동형을 받았고, 1945년 3월 27일 크라스노야르스크 지방의 수용소에서 작업 중 급사했다. 1955년 11월 26일 사후 복권되었다.$q$, $q$Voldemar Johannes Avgustovich Ulmer was born on 20 December 1896 in Reval (Tallinn), Estland province, to a working family of Swedish descent. He finished a four-year municipal school in Moscow, graduated from the 4th Kyiv school of ensigns in 1916 and served in the First World War; he had been a Bolshevik party member since 1914. From 1921 he held command and training posts in the border troops of the Cheka and OGPU, graduated from the Frunze Military Academy in 1928 and in July 1934 became head of the operational department of the border guard. He received the rank of brigade commander in December 1935.

On 16 April 1937 he became operational secretary of the Main Directorate of State Security in Yezhov's NKVD, the last gate through which the directorate's orders and instructions passed to the regional organs. The copies of Yezhov's orders for the mass operations of the Great Terror, beginning with Operational Order No. 00447 of 30 July 1937, end with the certification 'Certified: operational secretary of the GUGB NKVD USSR, brigade commander Ulmer'. This is why his name recurs in this site's 'NKVD operational orders' document and in the 1937 document collection. He did not write the orders; he vouched that they were authentic, and that signature made him one of the names most often met in the paper record of the terror.

Known as a protégé of Frinovsky, he became head of the secretariat of the new first deputy commissar, Beria, on 8 September 1938. As Naumov's research relates, Beria, who had brought only a handful of subordinates from Georgia, kept him for the first month out of necessity but did not trust him and soon replaced him with Merkulov. In November he was moved aside as acting deputy head of the convoy troops directorate. Arrested on 21 April 1939, he was sentenced by a military court in February 1940 to fifteen years of forced labour for membership of the 'conspiratorial terrorist organization of Yezhov, Frinovsky and Yevdokimov', and died suddenly at work in a camp in Krasnoyarsk region on 27 March 1945. He was posthumously rehabilitated on 26 November 1955.$q$, $q$["https://ru.wikipedia.org/wiki/Ульмер,_Вольдемар_Августович", "https://nkvd.memo.ru/index.php/Ульмер,_Вольдемар_Августович", "https://karagodin.org/?p=44108"]$q$::jsonb);
INSERT INTO commulingo_person_aliases (person_id, lang, alias, sort_order) VALUES ('voldemar-ulmer', 'ko', $q$울메르$q$, 0) ON CONFLICT DO NOTHING;
