INSERT INTO commulingo_history_event_people (event_id, person_id, sort_order, relation_kind, relation_ko, relation_en, note_ko, note_en) SELECT 'great-terror', 'voldemar-ulmer', COALESCE(MAX(sort_order),0)+1, 'executor', $q$국가보안총국 작전서기, 작전명령 인증 서명자$q$, $q$Operational secretary of the GUGB who certified the operational orders$q$, $q$1937년 4월부터 1938년 9월까지 국가보안총국 작전서기로 제00447호 등 대량 작전 명령 사본에 「확인함」 인증 서명을 했다. 1939년 체포되어 1945년 수용소에서 죽었다.$q$, $q$As operational secretary of the GUGB from April 1937 to September 1938 he certified the copies of the mass-operation orders, No. 00447 among them. Arrested in 1939, he died in a camp in 1945.$q$ FROM commulingo_history_event_people WHERE event_id='great-terror' ON CONFLICT DO NOTHING;
INSERT INTO commulingo_people (id, group_id, sort_order, initial, cyrillic, years_label, birth_year, death_year, name_ko, name_en, given_name_ko, given_name_en, family_name_ko, family_name_en, epithet_ko, epithet_en, bio_ko, bio_en, fate_kind, fate_label_ko, fate_label_en, citizenship_code, citizenship_label_ko, citizenship_label_en, origin_code, origin_label_ko, origin_label_en) SELECT 'hans-von-manteuffel-szoege', 'international-counterrevolutionary', COALESCE(MAX(sort_order),0)+1, '', $q$Hans Freiherr von Manteuffel-Szoege$q$, '1894–1919', 1894, 1919, $q$한스 폰 만토이펠-쇠게$q$, $q$Hans von Manteuffel-Szoege$q$, $q$한스$q$, $q$Hans$q$, $q$만토이펠-쇠게$q$, $q$Manteuffel-Szoege$q$, $q$리예파야 쿠데타를 이끌고 리가에서 전사한 발트 향토방위군 돌격대장$q$, $q$Baltic Landeswehr strike-troop commander who led the Liepāja coup and fell at Riga$q$, $q$쿠를란트의 발트 독일계 남작으로 1차 대전에서 바이에른군 창기병 장교로 싸웠고, 1919년 발트 향토방위군의 참모 장교 겸 돌격대장이 되었다. 4월 16일 리예파야에서 울마니스 정부를 뒤엎는 쿠데타를 이끌었고, 5월 22일 붉은 군대에서 리가를 탈환하는 공격 중 스물다섯 살에 전사했다.$q$, $q$A Baltic German baron from Courland who fought as a Bavarian uhlan officer in the First World War, he became a staff officer and strike-troop commander of the Baltic Landeswehr in 1919. On 16 April he led the Liepāja coup against the Ulmanis government, and on 22 May he was killed at twenty-five in the attack that retook Riga from the Red Army.$q$, 'killed', $q$1919년 리가 탈환 전투에서 전사$q$, $q$Killed in the recapture of Riga, 1919$q$, 'germany', $q$독일$q$, $q$Germany$q$, 'latvia', $q$쿠를란트 발트 독일계$q$, $q$Baltic German from Courland$q$ FROM commulingo_people WHERE group_id='international-counterrevolutionary' ON CONFLICT (id) DO NOTHING;
INSERT INTO commulingo_person_roles (person_id, category_id) VALUES ('hans-von-manteuffel-szoege', 'counterrevolution') ON CONFLICT DO NOTHING;
INSERT INTO commulingo_person_sections (person_id, slug, sort_order, heading_ko, heading_en, body_ko, body_en, sources) VALUES ('hans-von-manteuffel-szoege', 'independence-wars', 0, $q$1919년: 리예파야의 쿠데타에서 리가의 죽음까지$q$, $q$1919: from the coup at Liepāja to death at Riga$q$, $q$한스 폰 만토이펠-쇠게는 1894년 1월 19일 쿠를란트의 캅세덴 영지에서 발트 독일계 귀족 게오르크 폰 만토이펠-쇠게와 조피 폰 뤼디거 백작부인의 아들로 태어났다. 하이델베르크 대학에서 법학을 공부하며 학생조합 작소-보루시아에 속했고, 1차 대전이 나자 러시아 제국의 신민이면서도 바이에른군 제2창기병연대에 자원해 서부와 동부 전선에서 싸웠으며 1915년 소위가 되었다. 독일의 11월 혁명 뒤 쿠를란트로 돌아와 1919년 초 발트 독일계 지주층이 조직한 발트 향토방위군에 제1참모장교로 들어갔고, 참전 경험자를 모은 돌격대의 지휘관이 되었다.

향토방위군은 울마니스의 라트비아 임시정부를 형식상 지키고 있었지만, 독일계 병사들은 토지개혁을 약속하는 라트비아 국가에 복무할 뜻이 없었다. 1919년 4월 16일 만토이펠의 돌격대는 리예파야에서 정부를 급습해 각료들을 체포하려 했다. 울마니스는 영국 함정의 보호 아래 배 「사라토프」로 피신했다. 쿠데타는 연합국 사절단도, 폰 데어 골츠의 독일군 사령부도 공식적으로는 지지하지 않았지만, 골츠는 이를 묵인했고 5월 10일 목사 안드리에우스 니에드라의 친독 정부가 세워졌다. 5월 22일 향토방위군과 철사단은 붉은 군대에서 리가를 탈환했다. 만토이펠은 다우가바 강 다리를 건너 시내로 들어가는 선두에서 총에 맞아 죽었다. 스물다섯 살이었다.

발트 독일계 사이에서 그는 「가장 유능한 정치·군사 지도자」로 기억되었고, 그의 이름은 향토방위군 돌격대의 기념 훈장과 바이에른 슐리어제의 발트 전몰자 기념비에 남았다. 라트비아의 서술에서 그는 신생 공화국을 무너뜨리려 한 쿠데타의 주역이다. 리가 탈환 뒤 며칠 동안 이어진 처형과 보복, 6월 체시스에서 향토방위군이 에스토니아군에 패한 뒤 울마니스가 복귀한 경위는 「발트 독립전쟁」 문서에서 다룬다.$q$, $q$Hans von Manteuffel-Szoege was born on 19 January 1894 on the Kapseden estate in Courland, the son of the Baltic German noble Georg von Manteuffel-Szoege and Countess Sophie von Rüdiger. He studied law at Heidelberg, where he belonged to the student corps Saxo-Borussia, and when the First World War came he, though a subject of the Russian Empire, volunteered for the 2nd Bavarian Uhlan Regiment, fought on the western and eastern fronts and was commissioned lieutenant in 1915. After Germany's November revolution he returned to Courland and in early 1919 joined the Baltic Landeswehr, the force raised by the Baltic German landowners, as first general staff officer, becoming commander of its strike troop of war veterans.

The Landeswehr nominally defended Ulmanis's Latvian provisional government, but its German soldiers had no wish to serve a Latvian state that promised land reform. On 16 April 1919 Manteuffel's strike troop raided the government in Liepāja and tried to arrest the ministers; Ulmanis took refuge aboard the ship Saratov under British protection. Neither the Allied missions nor von der Goltz's German command supported the coup officially, but Goltz acquiesced, and on 10 May a pro-German government under the pastor Andrievs Niedra was installed. On 22 May the Landeswehr and the Iron Division retook Riga from the Red Army. Manteuffel was shot dead at the head of the troops crossing the Daugava bridge into the city. He was twenty-five.

Among Baltic Germans he was remembered as 'the most capable political and military leader' of their community, and his name survives on the commemorative badge of the Landeswehr strike troop and on the memorial to the Baltic fallen at Schliersee in Bavaria. In Latvian accounts he is the leading figure of the coup that tried to overthrow the young republic. The executions and reprisals of the days after the recapture of Riga, the Landeswehr's defeat by the Estonians at Cēsis in June and Ulmanis's return are told in the 'Baltic wars of independence' document.$q$, $q$["https://de.wikipedia.org/wiki/Hans_von_Manteuffel-Szoege", "https://www.deutsche-biographie.de/sfz57933.html", "https://en.wikipedia.org/wiki/Baltic_Landeswehr"]$q$::jsonb);
