INSERT INTO commulingo_person_aliases (person_id, lang, alias, sort_order) VALUES ('hans-von-manteuffel-szoege', 'en', $q$Baron Manteuffel$q$, 3) ON CONFLICT DO NOTHING;
INSERT INTO commulingo_history_event_people (event_id, person_id, sort_order, relation_kind, relation_ko, relation_en, note_ko, note_en) SELECT 'baltic-wars-of-independence', 'hans-von-manteuffel-szoege', COALESCE(MAX(sort_order),0)+1, 'leader', $q$리예파야 쿠데타를 이끈 향토방위군 돌격대장$q$, $q$Landeswehr strike-troop commander who led the Liepāja coup$q$, $q$1919년 4월 16일 리예파야에서 울마니스 정부를 뒤엎는 쿠데타를 이끌었고, 5월 22일 리가 탈환 공격의 선두에서 전사했다.$q$, $q$Led the coup against the Ulmanis government at Liepāja on 16 April 1919 and was killed at the head of the attack that retook Riga on 22 May.$q$ FROM commulingo_history_event_people WHERE event_id='baltic-wars-of-independence' ON CONFLICT DO NOTHING;
UPDATE commulingo_person_sections SET body_ko=$q$탈린의 법률가이자 신문 「테아타야」의 발행인으로 1905년 혁명 뒤 사형을 선고받고 망명했다. 1918년 2월 24일 구원위원회의 독립 선언을 이끌었고 독일 점령군에 억류되었다가 11월 임시정부 수반으로 권력을 넘겨받았다. 독립전쟁 첫 겨울 붉은 군대가 탈린 34킬로미터 앞까지 왔을 때 정부를 지켰고, 영국 함대의 지원과 라이도네르의 임명, 강제 징집을 관철했다. 1920년대 여러 차례 국가원로(총리)를 지냈고, 1934년 3월 극우 참전용사 운동의 집권을 막는다는 명분으로 라이도네르와 함께 계엄을 선포한 뒤 의회를 정지시키고 「침묵의 시대」라 불리는 권위주의 체제를 세워 1938년 초대 대통령이 되었다. 1940년 소련 점령 뒤 강제이송되어 정신병원과 감옥을 거쳐 1956년 칼리닌 주의 병원에서 죽었다.$q$, body_en=$q$A Tallinn lawyer and publisher of the newspaper Teataja, sentenced to death after the 1905 revolution and forced into exile. He led the Salvation Committee's declaration of independence on 24 February 1918, was interned by the German occupiers and took over as head of the provisional government in November. In the first winter of the independence war, with the Red Army 34 kilometres from Tallinn, he held the government together and pushed through British naval support, Laidoner's appointment and conscription. He served several terms as State Elder in the 1920s, and in March 1934, claiming to forestall a takeover by the far-right veterans' movement, he declared a state of emergency with Laidoner, suspended parliament and built the authoritarian regime known as the 'era of silence', becoming the first president in 1938. Deported after the Soviet occupation of 1940, he passed through psychiatric hospitals and prisons and died in a hospital in Kalinin region in 1956.$q$, updated_at=now() WHERE person_id='konstantin-pats' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1918년 2월 에스토니아 독립 선언을 이끌고 독립전쟁 첫 겨울 임시정부 수반으로 나라를 지켰다. 1934년 라이도네르와 함께 「침묵의 시대」의 권위주의 체제를 세웠고 1940년 소련에 강제이송되어 1956년 구금 중 죽었다.$q$, bio_en=$q$Led Estonia's declaration of independence in February 1918 and held the country together as head of the provisional government in the first winter of the independence war. In 1934 he built the authoritarian 'era of silence' with Laidoner; deported by the Soviets in 1940, he died in custody in 1956.$q$, updated_at=now() WHERE id='konstantin-pats';
UPDATE commulingo_person_sections SET body_ko=$q$러시아 제국군 참모 장교로 1차 대전을 치르고 1917년 에스토니아 부대 편성에 참여했다. 1918년 12월 23일 총사령관에 임명되어 장갑열차와 의용 대대로 기동 부대를 만들고 강제 징집을 관철해 1919년 1월 반격을 이끌었으며, 6월 체시스 전투에서 에스토니아군과 북라트비아 여단을 지휘해 독일 향토방위군을 격파했다. 유데니치의 북서군과는 조건부로 협력하되 페트로그라드 공격에는 가담하지 않았고, 타르투 강화 뒤 1920년 3월 사령관직을 내놓았다. 의회 의원과 국제연맹의 모술 국경 조사관을 지냈고, 1924년 공산당 봉기 진압 때 다시 총사령관이 되었다. 1934년 페츠와 함께 계엄을 선포하고 권위주의 체제의 군부 축을 맡았다. 1940년 소련에 강제이송되어 1953년 블라디미르 감옥에서 죽었다.$q$, body_en=$q$A general staff officer of the Russian imperial army in the First World War, he helped form Estonian national units in 1917. Appointed commander-in-chief on 23 December 1918, he built mobile forces from armoured trains and volunteer battalions, enforced conscription and led the counteroffensive of January 1919; in June he commanded the Estonian troops and the Northern Latvian brigade that defeated the German Landeswehr at Cēsis. He cooperated conditionally with Yudenich's Northwestern Army but took no part in the attack on Petrograd, and resigned his command in March 1920 after the Treaty of Tartu. He sat in parliament and served as the League of Nations' investigator on the Mosul frontier, and returned as commander-in-chief to put down the communist rising of 1924. In 1934 he declared the state of emergency with Päts and became the military pillar of the authoritarian regime. Deported to the Soviet Union in 1940, he died in Vladimir prison in 1953.$q$, updated_at=now() WHERE person_id='johan-laidoner' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1918년 12월 에스토니아군 총사령관이 되어 1919년 1월 반격과 6월 체시스 전투를 이끌었다. 1934년 페츠의 계엄 체제를 떠받쳤고 1940년 소련에 강제이송되어 1953년 블라디미르 감옥에서 죽었다.$q$, bio_en=$q$Commander-in-chief of the Estonian army from December 1918, he led the counteroffensive of January 1919 and the battle of Cēsis in June. He propped up Päts's emergency regime in 1934 and, deported by the Soviets in 1940, died in Vladimir prison in 1953.$q$, updated_at=now() WHERE id='johan-laidoner';
UPDATE commulingo_person_sections SET body_ko=$q$타르투의 신문 「포스티메스」를 1896년부터 이끌며 에스토니아 민족운동의 자유주의 진영을 대표했고, 1905년 진보인민당을 창당해 러시아 두마 의원을 지냈다. 1917년 임시정부에 에스토니아 자치를 요구하는 대표단을 이끌었고 독립 선언 뒤 서방에서 승인을 구했다. 1919년 11월 총리가 되어 12월 타르투에서 시작된 소비에트 러시아와의 강화 협상을 뒷받침했고, 1920년 2월 2일 조약이 그의 정부 아래 체결되었다. 1920년대 국가원로와 의회 의장을 지냈으며 1933년 마지막으로 국가원로가 되었다. 1934년 페츠의 권위주의 체제에 반대해 「포스티메스」를 빼앗기고 정치에서 밀려났다. 1940년 소련 점령 뒤 체포되어 실종되었으며, 1941년 탈린에서 처형된 것으로 추정된다.$q$, body_en=$q$Editor of the Tartu newspaper Postimees from 1896, he represented the liberal wing of the Estonian national movement, founded the Progressive People's Party in 1905 and sat in the Russian Duma. In 1917 he led the delegation demanding Estonian autonomy from the Provisional Government and after the declaration of independence sought recognition in the West. He became prime minister in November 1919 and backed the peace talks with Soviet Russia that opened at Tartu in December; the treaty of 2 February 1920 was signed under his government. He served as State Elder and speaker of parliament in the 1920s and was State Elder for the last time in 1933. Opposing Päts's authoritarian regime in 1934, he lost Postimees and was pushed out of politics. Arrested after the Soviet occupation of 1940, he disappeared and is presumed to have been executed in Tallinn in 1941.$q$, updated_at=now() WHERE person_id='jaan-tonisson' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$「포스티메스」를 이끈 에스토니아 자유주의 민족운동의 대표로 1919~1920년 총리를 지내며 타르투 강화를 체결했다. 1934년 페츠의 권위주의 체제에 반대해 밀려났고 1940년 소련 점령 뒤 체포되어 실종되었다.$q$, bio_en=$q$Leader of Estonia's liberal national movement through the newspaper Postimees, he was prime minister in 1919 and 1920 and concluded the Treaty of Tartu. Pushed out for opposing Päts's authoritarian regime in 1934, he was arrested after the Soviet occupation of 1940 and disappeared.$q$, updated_at=now() WHERE id='jaan-tonisson';
UPDATE commulingo_person_sections SET body_ko=$q$1905년 혁명 뒤 미국으로 망명해 네브래스카 대학에서 농학을 공부하고 돌아온 농민연합의 지도자였다. 1918년 11월 18일 인민평의회가 독립을 선포하면서 임시정부 총리가 되었고, 붉은 군대가 리가를 점령한 1919년 1월 리예파야로 물러나 독일 향토방위군과 자유군단에 기대어 정부를 유지했다. 4월 독일계 쿠데타로 영국 함정이 보호하는 배 「사라토프」로 피신했다가 체시스 전투 뒤 7월 리가로 돌아왔고, 베르몬트군의 리가 공격을 막아 냈으며 1920년 8월 소비에트 러시아와의 리가 강화와 9월 토지개혁을 이끌었다. 1920년대 여러 차례 총리를 지냈고 1934년 5월 15일 쿠데타로 의회와 정당을 해산해 독재를 세운 뒤 1936년 대통령직까지 겸했다. 1940년 소련 점령 뒤 강제이송되어 1942년 투르크메니스탄 크라스노보츠크의 감옥에서 죽었다.$q$, body_en=$q$Leader of the Farmers' Union who had fled to the United States after 1905 and studied agriculture at the University of Nebraska. When the People's Council proclaimed independence on 18 November 1918 he became prime minister of the provisional government; after the Red Army took Riga in January 1919 he withdrew to Liepāja and kept the government alive by leaning on the German Landeswehr and Freikorps. Driven by the German coup of April onto the ship Saratov under British protection, he returned to Riga in July after Cēsis, saw off Bermondt's attack on the city and led Latvia through the Treaty of Riga with Soviet Russia in August 1920 and the land reform of September. He was prime minister several times in the 1920s, and on 15 May 1934 dissolved parliament and the parties in a coup, adding the presidency to his powers in 1936. Deported after the Soviet occupation of 1940, he died in prison at Krasnovodsk in Turkmenistan in 1942.$q$, updated_at=now() WHERE person_id='karlis-ulmanis' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1918년 11월부터 라트비아 임시정부 총리로 소비에트군, 독일계 쿠데타, 베르몬트군을 차례로 넘기고 1920년 리가 강화와 토지개혁을 이끌었다. 1934년 쿠데타로 독재를 세웠고 1940년 소련에 강제이송되어 1942년 감옥에서 죽었다.$q$, bio_en=$q$Prime minister of Latvia's provisional government from November 1918, he survived the Soviet army, a German coup and Bermondt's army in turn and led the Riga peace and land reform of 1920. He set up a dictatorship by coup in 1934 and, deported by the Soviets in 1940, died in prison in 1942.$q$, updated_at=now() WHERE id='karlis-ulmanis';
UPDATE commulingo_person_sections SET body_ko=$q$루터교 목사이자 라트비아 문학의 대표적 소설가로, 1905년 혁명에 반대해 독일계 지주층과 협력하는 보수 노선을 취했다. 1919년 4월 16일 리예파야 쿠데타로 울마니스 정부가 쫓겨난 뒤 5월 10일 폰 데어 골츠의 지원을 받는 정부의 수반이 되었고, 5월 22일 독일계 부대가 리가를 탈환하자 리가에 들어갔다. 6월 체시스 전투에서 독일 향토방위군이 에스토니아군에 패하고 7월 연합국 중재로 울마니스가 복귀하면서 정권은 무너졌다. 독일로 피했다가 1924년 라트비아로 돌아와 국가반역죄로 재판을 받고 추방되었다. 1942년 리가에서 죽었다. 라트비아에서 그의 이름은 오랫동안 「배신자」와 동의어였고, 문학사에서의 평가와 정치사에서의 평가가 갈린다.$q$, body_en=$q$A Lutheran pastor and one of the leading novelists of Latvian literature, he opposed the revolution of 1905 and took a conservative line of cooperation with the Baltic German landowners. After the Liepāja coup of 16 April 1919 drove out the Ulmanis government he became head of a government backed by von der Goltz on 10 May, and entered Riga when the German formations retook it on 22 May. His regime collapsed when the Landeswehr was beaten by the Estonians at Cēsis in June and Ulmanis returned under Allied mediation in July. He fled to Germany, returned to Latvia in 1924, was tried for treason and expelled. He died in Riga in 1942. In Latvia his name long served as a synonym for 'traitor', and his standing in literary history diverges from his standing in political history.$q$, updated_at=now() WHERE person_id='andrievs-niedra' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$라트비아 문학의 대표적 소설가이자 루터교 목사로 1919년 5월 리예파야 쿠데타 뒤 폰 데어 골츠가 뒷받침한 친독 정부의 수반이 되었다. 체시스 전투 뒤 정권이 무너져 독일로 피했고 1924년 귀국해 국가반역죄로 추방되었다.$q$, bio_en=$q$A leading Latvian novelist and Lutheran pastor, he headed the pro-German government backed by von der Goltz after the Liepāja coup of 1919. His regime fell after Cēsis, he fled to Germany and, returning in 1924, was tried for treason and expelled.$q$, updated_at=now() WHERE id='andrievs-niedra';
UPDATE commulingo_person_sections SET body_ko=$q$리가 공업대학 출신의 은행원으로 1918년 라트비아 임시민족평의회의 대표로 런던에 파견되어 11월 11일 영국 외무장관 밸푸어에게서 사실상의 승인을 얻어 냈다. 독립 선포 뒤 초대 외무장관이 되어 파리 강화회의에서 연합국의 지지를 구했고, 독일 자유군단과 베르몬트군 문제에서 연합국 사절단을 움직여 독일군의 철수를 이끌어 냈다. 1920년 8월 소비에트 러시아와의 리가 강화와 1921년 1월 연합국의 법적 승인, 그해 9월 국제연맹 가입이 그의 외교의 결과였다. 1921년부터 1923년까지 총리를 겸했고 발트 3국과 핀란드, 폴란드의 협력 구상을 추진했다. 1925년 8월 교통사고로 서른여덟에 죽었다.$q$, body_en=$q$A bank clerk trained at the Riga Polytechnic, he was sent to London in 1918 as the representative of the Latvian Provisional National Council and on 11 November obtained de facto recognition from the British foreign secretary Balfour. After the proclamation of independence he became the first foreign minister, sought Allied support at the Paris Peace Conference and worked the Allied missions to secure the withdrawal of the German Freikorps and Bermondt's troops. The Treaty of Riga with Soviet Russia in August 1920, de jure recognition by the Allies in January 1921 and admission to the League of Nations that September were the results of his diplomacy. He was also prime minister from 1921 to 1923 and promoted cooperation among the Baltic states, Finland and Poland. He died in a road accident in August 1925 at the age of thirty-eight.$q$, updated_at=now() WHERE person_id='zigfrids-meierovics' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$라트비아의 초대 외무장관으로 1918년 영국의 사실상 승인, 1920년 리가 강화, 1921년 연합국의 법적 승인과 국제연맹 가입을 얻어 냈다. 총리도 지냈으며 1925년 교통사고로 서른여덟에 죽었다.$q$, bio_en=$q$Latvia's first foreign minister, he won de facto British recognition in 1918, the Riga peace of 1920, and de jure Allied recognition and League membership in 1921. He also served as prime minister and died in a road accident in 1925 at thirty-eight.$q$, updated_at=now() WHERE id='zigfrids-meierovics';
UPDATE commulingo_person_sections SET body_ko=$q$프로이센 장군으로 1918년 4월 발트 사단 약 1만 명을 이끌고 항코에 상륙해 헬싱키를 점령하고 핀란드 백군의 승리를 도왔으며, 그해 말까지 핀란드에 머물러 독일의 영향력을 굳히려 했다. 1919년 2월 리예파야에서 제6예비군단 사령관으로 독일 정규군 잔류 병력과 철사단, 발트 향토방위군을 지휘해 붉은 군대에서 리가를 탈환했지만, 라트비아 독립정부를 장애물로 여겨 4월 리예파야 쿠데타와 니에드라 정부를 뒷받침했다. 6월 체시스에서 에스토니아군에 패하고 연합국의 압력으로 10월 소환되었으며, 그의 병력 다수는 베르몬트-아발로프의 서러시아 의용군에 합류했다. 바이마르 공화국에서 극우 퇴역군인 단체를 이끌었고 1920년 카프 쿠데타에 연루되었다. 1946년 바이에른에서 죽었다.$q$, body_en=$q$A Prussian general who in April 1918 landed some 10,000 men of the Baltic Sea Division at Hanko, took Helsinki and helped the Finnish Whites to victory, staying in Finland until the end of the year to entrench German influence. In February 1919 at Liepāja he took command of the VI Reserve Corps, the remaining German regulars, the Iron Division and the Baltic Landeswehr, and retook Riga from the Red Army, but he treated Latvia's independence government as an obstacle and backed the Liepāja coup of April and the Niedra government. Beaten by the Estonians at Cēsis in June and recalled under Allied pressure in October, he saw most of his men join Bermondt-Avalov's West Russian Volunteer Army. In the Weimar Republic he led far-right veterans' organizations and was implicated in the Kapp putsch of 1920. He died in Bavaria in 1946.$q$, updated_at=now() WHERE person_id='rudiger-von-der-goltz' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1918년 발트 사단을 이끌고 핀란드 백군을 도운 뒤 1919년 라트비아에서 독일군과 자유군단을 지휘해 리가를 탈환했으나, 라트비아 정부를 장애물로 여겨 쿠데타를 뒷받침했다. 체시스 패배 뒤 소환되었고 바이마르 시기 극우 퇴역군인 운동을 이끌었다.$q$, bio_en=$q$He led the Baltic Sea Division to the aid of the Finnish Whites in 1918, then commanded the German troops and Freikorps in Latvia in 1919, retaking Riga but backing a coup against the Latvian government he saw as an obstacle. Recalled after Cēsis, he led far-right veterans' movements in the Weimar years.$q$, updated_at=now() WHERE id='rudiger-von-der-goltz';
UPDATE commulingo_person_sections SET body_ko=$q$러시아 제국군의 기병 장교 출신으로 스스로 그루지야 공가의 후예를 자칭해 「아발로프 공」이라는 이름을 썼다. 1919년 독일에서 러시아인 포로로 반볼셰비키 부대를 조직해 라트비아로 들어왔고, 연합국의 철수 요구를 거부한 폰 데어 골츠의 독일 병사 수만 명을 받아들여 서러시아 의용군을 만들었다. 유데니치가 페트로그라드로 진격하던 10월, 그는 북서군에 합류하라는 명령을 거부하고 10월 8일 리가를 공격해 다우가바 서안 교외를 점령했다. 라트비아군이 영국·프랑스 함정의 지원으로 11월 11일 반격에 성공하고 리투아니아군이 라드빌리슈키스에서 그의 부대를 격파하면서 12월 독일로 철수했다. 망명 뒤 베를린에서 러시아 파시스트 조직을 이끌었고, 1939년 나치 독일에서 추방되어 미국으로 갔으며 1973년 뉴욕에서 죽었다. 출신에 관한 자료가 서로 어긋나 출신 국가는 비워 두었다.$q$, body_en=$q$A cavalry officer of the Russian imperial army who styled himself 'Prince Avalov', claiming descent from a Georgian princely house. In 1919 he organized an anti-Bolshevik force from Russian prisoners in Germany, brought it to Latvia and absorbed tens of thousands of von der Goltz's German soldiers who refused the Allied demand to leave, forming the West Russian Volunteer Army. In October, while Yudenich was advancing on Petrograd, he refused the order to join the Northwestern Army and instead attacked Riga on 8 October, seizing the suburbs on the west bank of the Daugava. When the Latvian army counterattacked successfully on 11 November with the support of British and French warships and the Lithuanians defeated his troops at Radviliškis, he withdrew to Germany in December. In exile he led a Russian fascist organization in Berlin, was expelled from Nazi Germany in 1939 and went to the United States, where he died in New York in 1973. Sources disagree about his origins, so his country of origin is left blank.$q$, updated_at=now() WHERE person_id='pavel-bermondt-avalov' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$「아발로프 공」을 자칭한 러시아 기병 장교로 1919년 철수를 거부한 독일 자유군단 수만 명을 서러시아 의용군으로 묶어 10월 리가를 공격했다가 격퇴되었다. 망명 뒤 베를린에서 러시아 파시스트 조직을 이끌었고 1973년 뉴욕에서 죽었다.$q$, bio_en=$q$A Russian cavalry officer who styled himself 'Prince Avalov', he gathered tens of thousands of German Freikorps men who refused to leave Latvia into the West Russian Volunteer Army and attacked Riga in October 1919, only to be repelled. In exile he led a Russian fascist organization in Berlin and died in New York in 1973.$q$, updated_at=now() WHERE id='pavel-bermondt-avalov';
UPDATE commulingo_person_sections SET body_ko=$q$페테르부르크에서 법을 공부한 언론인으로 1917년 9월 독일 점령 아래 구성된 리투아니아 평의회(타리바)의 의장이 되어 1918년 2월 16일 독립 선언에 서명했다. 독일과의 동맹을 전제로 한 12월 선언에도 서명했고 1918년 7월 우라흐 공의 국왕 추대에도 관여해 독립운동 안에서 논쟁을 남겼다. 1919년 4월 국가평의회에서 초대 대통령에 선출되어 붉은 군대, 베르몬트군, 폴란드군과 싸우는 첫 정부들을 이끌었고, 1920년 제헌의회가 열리자 물러났다. 1926년 12월 군부 쿠데타로 다시 대통령이 되어 정당을 금지하고 권위주의 체제를 세웠으며, 1938년 폴란드 최후통첩과 1939년 독일의 클라이페다 병합을 겪었다. 1940년 6월 소련의 최후통첩에 저항을 주장했다가 독일로 피신해 미국으로 갔고, 1944년 클리블랜드에서 화재로 죽었다.$q$, body_en=$q$A journalist who had studied law in St Petersburg, he chaired the Lithuanian Council (Taryba) formed under German occupation in September 1917 and signed the declaration of independence of 16 February 1918. He had also signed the December declaration premised on alliance with Germany and took part in the election of Duke Wilhelm of Urach as king in July 1918, leaving a controversy inside the independence movement. Elected first president by the State Council in April 1919, he led the first governments that fought the Red Army, Bermondt's troops and the Polish army, and stepped down when the Constituent Assembly met in 1920. A military coup in December 1926 made him president again; he banned the parties and built an authoritarian regime, and lived through the Polish ultimatum of 1938 and Germany's seizure of Klaipėda in 1939. Urging resistance to the Soviet ultimatum of June 1940, he fled to Germany and then the United States, where he died in a house fire in Cleveland in 1944.$q$, updated_at=now() WHERE person_id='antanas-smetona' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$리투아니아 평의회 의장으로 1918년 독립 선언에 서명하고 1919년 초대 대통령이 되어 붉은 군대, 베르몬트군, 폴란드군과 싸우는 첫 정부들을 이끌었다. 1926년 쿠데타로 권위주의 체제를 세웠고 1940년 소련 점령 뒤 미국으로 피해 1944년 화재로 죽었다.$q$, bio_en=$q$Chairman of the Lithuanian Council, he signed the 1918 declaration of independence and as first president from 1919 led the governments that fought the Red Army, Bermondt's troops and the Poles. He built an authoritarian regime after the 1926 coup and, fleeing the Soviet occupation of 1940, died in a fire in the United States in 1944.$q$, updated_at=now() WHERE id='antanas-smetona';
UPDATE commulingo_person_sections SET body_ko=$q$페테르부르크 대학에서 고대사를 가르친 역사학자로 1917년 리투아니아 평의회에 들어가 1918년 11월 11일 첫 내각의 총리 겸 외무장관이 되었다. 「리투아니아에는 적이 없다」며 군대 창설을 늦추었다가 붉은 군대의 진입 앞에서 12월 사퇴했으나, 이후 외무장관으로 파리 강화회의와 국제연맹에서 빌뉴스 문제를 다투었다. 1926년 12월 쿠데타 뒤 다시 총리가 되어 1927년 의회를 해산하고 극우 조직 「철의 늑대」를 이끌었으나, 1929년 스메토나와 갈라져 해임되었고 1934년 쿠데타 시도로 투옥된 뒤 국외로 추방되었다. 1940년 소련 점령 직후 귀국하다 체포되었고 1942년 모스크바의 감옥에서 죽었다.$q$, body_en=$q$A historian who taught ancient history at St Petersburg University, he joined the Lithuanian Council in 1917 and on 11 November 1918 became prime minister and foreign minister of the first cabinet. Declaring that 'Lithuania has no enemies', he delayed creating an army and resigned in December as the Red Army approached, but as foreign minister he then fought the Vilnius question at the Paris Peace Conference and the League of Nations. Prime minister again after the coup of December 1926, he dissolved parliament in 1927 and led the far-right Iron Wolf, but broke with Smetona and was dismissed in 1929, imprisoned after an attempted coup in 1934 and expelled from the country. Returning just after the Soviet occupation of 1940, he was arrested and died in a Moscow prison in 1942.$q$, updated_at=now() WHERE person_id='augustinas-voldemaras' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1918년 11월 리투아니아 첫 내각의 총리 겸 외무장관이 되었고 이후 파리와 국제연맹에서 빌뉴스 문제를 다투었다. 1926년 쿠데타 뒤 다시 총리가 되어 극우 「철의 늑대」를 이끌다 스메토나와 갈라졌고, 1942년 소련 감옥에서 죽었다.$q$, bio_en=$q$Prime minister and foreign minister of Lithuania's first cabinet in November 1918, he later fought the Vilnius question in Paris and at the League of Nations. Prime minister again after the 1926 coup, he led the far-right Iron Wolf, broke with Smetona and died in a Soviet prison in 1942.$q$, updated_at=now() WHERE id='augustinas-voldemaras';
UPDATE commulingo_person_sections SET body_ko=$q$빈차스 미츠케비추스-카프수카스는 리투아니아 사회민주당의 활동가로 1905년 혁명 뒤 유형과 망명을 거쳐 1917년 볼셰비키에 합류했고, 1918년 10월 리투아니아 공산당 창립을 이끌었다. 1918년 12월 16일 붉은 군대의 진입과 함께 리투아니아 소비에트 정부의 수반으로 선포되었고, 1919년 1월 빌뉴스에 들어가 2월 리투아니아-벨로루시 소비에트 공화국(리트벨) 정부를 이끌었다. 대농장을 국영 농장으로 만드는 정책은 농민의 지지를 얻지 못했고, 4월 폴란드군이 빌뉴스를 점령하면서 정부는 민스크로, 이어 러시아로 물러났다. 이후 코민테른 집행위원회에서 발트 문제를 맡았고 리투아니아 공산당을 지하에서 지도했으며 1935년 모스크바에서 죽었다. 소비에트 리투아니아 시절 그의 이름은 대학과 도시에 붙었고 1990년 이후 지워졌다.$q$, body_en=$q$Vincas Mickevičius-Kapsukas, an activist of the Lithuanian Social Democratic Party, passed through exile and emigration after 1905, joined the Bolsheviks in 1917 and led the founding of the Lithuanian Communist Party in October 1918. Proclaimed head of the Soviet government of Lithuania on 16 December 1918 as the Red Army advanced, he entered Vilnius in January 1919 and in February headed the government of the Lithuanian-Belorussian Soviet Republic, Litbel. Its policy of turning the large estates into state farms won no peasant support, and when Polish troops took Vilnius in April the government withdrew to Minsk and then to Russia. He later handled Baltic affairs on the Comintern executive and directed the underground Lithuanian party, and died in Moscow in 1935. Under Soviet rule his name was given to a university and a city; after 1990 it was removed.$q$, updated_at=now() WHERE person_id='vincas-kapsukas' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$리투아니아 공산당의 창설자로 1918년 12월 소비에트 리투아니아 정부의 수반이 되고 1919년 리트벨을 이끌었으나 농민의 지지를 얻지 못했다. 패배 뒤 코민테른에서 발트 문제를 맡았고 1935년 모스크바에서 죽었다.$q$, bio_en=$q$Founder of the Lithuanian Communist Party, he headed the Soviet government of Lithuania from December 1918 and Litbel in 1919, without winning peasant support. After the defeat he handled Baltic affairs in the Comintern and died in Moscow in 1935.$q$, updated_at=now() WHERE id='vincas-kapsukas';
UPDATE commulingo_person_sections SET body_ko=$q$지그마스 알렉사-안가리에티스는 바르샤바 수의학교 출신의 사회민주당원으로 1909년 체포되어 시베리아 유형을 살고 1917년 페트로그라드에서 볼셰비키 리투아니아 지부를 조직했다. 1918년 12월 카프수카스의 소비에트 리투아니아 정부에서 내무 인민위원을 맡았고 1919년 리트벨 정부에도 참여했다. 패배 뒤 소비에트 러시아에서 리투아니아 공산당의 국외 지도부를 이끌며 코민테른 집행위원회 위원, 국제통제위원회 위원으로 일했고 리투아니아 노동운동사를 여러 권 썼다. 카프수카스와의 노선 논쟁으로 당내에서 밀려났으며, 1938년 체포되어 1940년 5월 모스크바에서 처형되었다.$q$, body_en=$q$Zigmas Aleksa-Angarietis, a Social Democrat trained at the Warsaw veterinary institute, was arrested in 1909, served Siberian exile and in 1917 organized the Lithuanian section of the Bolsheviks in Petrograd. In December 1918 he became commissar for internal affairs in Kapsukas's Soviet government of Lithuania and in 1919 joined the Litbel government. After the defeat he led the Lithuanian party's leadership abroad from Soviet Russia, sat on the Comintern executive and its International Control Commission and wrote several volumes on the history of the Lithuanian labour movement. Sidelined in the party after a line dispute with Kapsukas, he was arrested in 1938 and shot in Moscow in May 1940.$q$, updated_at=now() WHERE person_id='zigmas-angarietis' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$리투아니아 공산당 지도자로 1918~1919년 소비에트 리투아니아와 리트벨의 내무 인민위원을 지냈다. 망명 뒤 코민테른에서 일하며 리투아니아 노동운동사를 썼고, 1938년 체포되어 1940년 처형되었다.$q$, bio_en=$q$A Lithuanian communist leader, he was commissar for internal affairs of Soviet Lithuania and Litbel in 1918 and 1919. In exile he worked in the Comintern and wrote the history of the Lithuanian labour movement; arrested in 1938, he was shot in 1940.$q$, updated_at=now() WHERE id='zigmas-angarietis';
UPDATE commulingo_person_sections SET body_ko=$q$러시아 제국군 장교로 1917년 러시아 안의 폴란드 부대를 지휘했고 1919년 폴란드군에 합류해 소비에트-폴란드 전쟁에서 사단과 군을 지휘했다. 1920년 10월 7일 수바우키 협정이 빌뉴스를 리투아니아 쪽에 남기자, 피우수트스키와 사전에 협의한 대로 10월 8일 리투아니아-벨로루시 제1사단 약 1만 4천 명을 이끌고 「항명」을 선언해 다음 날 빌뉴스를 점령했다. 그가 세운 「중부 리투아니아」는 1922년 폴란드에 편입되었고, 이 사건은 1938년까지 폴란드와 리투아니아의 국교를 막았다. 1925년부터 1926년까지 국방장관을 지냈고, 2차 대전 때 망명 정부의 국민평의회에서 활동하다 1947년 런던에서 죽었다. 유언에 따라 빌뉴스에 묻히기를 원했으나 바르샤바에 안장되었다.$q$, body_en=$q$An officer of the Russian imperial army who commanded Polish units in Russia in 1917, he joined the Polish army in 1919 and led divisions and an army in the Soviet-Polish War. When the Suwałki Agreement of 7 October 1920 left Vilnius on the Lithuanian side, he declared a 'mutiny' on 8 October, as arranged beforehand with Piłsudski, and led the 1st Lithuanian-Belorussian Division of about 14,000 men into Vilnius the next day. The 'Central Lithuania' he set up was incorporated into Poland in 1922, and the affair blocked diplomatic relations between Poland and Lithuania until 1938. He was minister of military affairs in 1925 and 1926, served on the National Council of the government in exile in the Second World War and died in London in 1947. He had asked to be buried in Vilnius; he was buried in Warsaw.$q$, updated_at=now() WHERE person_id='lucjan-zeligowski' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$러시아 제국군 출신 폴란드 장군으로 1920년 10월 9일 피우수트스키와 협의한 「항명」으로 빌뉴스를 점령해 중부 리투아니아를 세웠다. 이 사건은 1938년까지 폴란드와 리투아니아의 국교를 막았다. 1947년 런던에서 죽었다.$q$, bio_en=$q$A Polish general from the Russian imperial army, he seized Vilnius on 9 October 1920 in a 'mutiny' agreed with Piłsudski and set up Central Lithuania, an affair that blocked Polish-Lithuanian relations until 1938. He died in London in 1947.$q$, updated_at=now() WHERE id='lucjan-zeligowski';
UPDATE commulingo_person_sections SET body_ko=$q$빌뉴스 근교의 벨로루시-폴란드계 가정 출신으로 1차 대전에서 러시아 제국군 기병 장교로 싸웠고, 1918년 붉은 군대에 잠시 있다가 프스코프의 백군 북부군단으로 넘어갔다. 1919년 5월 25일 그의 부대가 프스코프를 점령했고, 그곳에서 벌인 처형과 유대인 주민 학대는 백군 안에서도 문제가 되었다. 유데니치와 갈라져 에스토니아군 편에 섰고, 1920년 1월 해산 직전의 유데니치를 잠시 억류하는 소동을 벌인 뒤 부대와 함께 폴란드로 옮겨 피우수트스키 아래에서 싸웠다. 10월 휴전 뒤 폴란드의 묵인 아래 독자적으로 벨로루시 인민공화국을 내걸고 모지르로 원정했으나 11월 패퇴했고, 이 원정에서도 부대의 반유대인 폭력이 기록되어 있다. 폴란드 시민으로 1939년 바르샤바 방어전에 의용대를 이끌었고, 1940년 독일 점령 아래 바르샤바에서 피살되었다.$q$, body_en=$q$Born to a Belarusian-Polish family near Vilnius, he fought as a cavalry officer of the Russian imperial army in the First World War, served briefly in the Red Army in 1918 and went over to the White Northern Corps at Pskov. His troops took Pskov on 25 May 1919, and the executions and abuse of Jewish inhabitants there caused trouble even within the White camp. He broke with Yudenich and sided with the Estonians, briefly detained Yudenich in January 1920 on the eve of the Northwestern Army's dissolution, and then took his men to Poland to fight under Piłsudski. After the armistice of October he marched independently on Mozyr under the banner of a Belarusian People's Republic with Polish acquiescence, was beaten in November, and this campaign too is recorded for his troops' anti-Jewish violence. As a Polish citizen he led volunteers in the defence of Warsaw in 1939, and was killed in occupied Warsaw in 1940.$q$, updated_at=now() WHERE person_id='stanislaw-bulak-balachowicz' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$붉은 군대에서 백군으로 넘어가 1919년 프스코프를 점령하고 유데니치와 갈라져 에스토니아 편에 섰다가 1920년 폴란드로 옮겨 벨로루시 원정을 벌였다. 부대의 반유대인 폭력이 기록되어 있으며 1940년 독일 점령 바르샤바에서 피살되었다.$q$, bio_en=$q$He went from the Red Army to the Whites, took Pskov in 1919, broke with Yudenich to side with Estonia and in 1920 moved to Poland for a Belarusian expedition. His troops' anti-Jewish violence is on record; he was killed in occupied Warsaw in 1940.$q$, updated_at=now() WHERE id='stanislaw-bulak-balachowicz';
UPDATE commulingo_person_sections SET body_ko=$q$법률가이자 판사로 러시아화 정책에 저항해 1914년 시베리아로 유배되었고, 1917년 3월 돌아와 11월 원로원(정부) 수반이 되어 12월 6일 독립 선언을 이끌었으며 12월 말 페트로그라드에서 레닌의 승인을 직접 받아 냈다. 1918년 1월 내전이 시작되자 적위대가 장악한 헬싱키에서 탈출해 바사의 백색정부를 이끌었고, 만네르헤임의 반대를 무릅쓰고 독일에 군사 개입을 요청해 폰 데어 골츠의 발트 사단을 불러들였다. 5월 섭정이 되었으나 독일의 패전으로 친독 노선이 무너지자 12월 만네르헤임에게 자리를 넘겼다. 1930년 총리, 1931년부터 1937년까지 대통령을 지내며 극우 라푸아 운동의 1932년 멘첼레 반란을 라디오 연설로 진압했다. 1944년 죽었다.$q$, body_en=$q$A lawyer and judge exiled to Siberia in 1914 for resisting Russification, he returned in March 1917, became head of the Senate, Finland's government, in November, led the declaration of independence on 6 December and at the end of December obtained Lenin's recognition in person in Petrograd. When civil war began in January 1918 he escaped from Red-held Helsinki and led the White government at Vaasa, and over Mannerheim's objections asked Germany for military intervention, bringing in von der Goltz's Baltic Sea Division. He became regent in May, but when Germany's defeat wrecked the pro-German line he handed the post to Mannerheim in December. Prime minister in 1930 and president from 1931 to 1937, he put down the far-right Lapua movement's Mäntsälä rebellion of 1932 with a radio address. He died in 1944.$q$, updated_at=now() WHERE person_id='pehr-evind-svinhufvud' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1917년 12월 핀란드 독립 선언을 이끈 원로원 수반으로 1918년 내전에서 백색정부를 이끌며 독일의 개입을 요청했다. 1931년부터 1937년까지 대통령을 지냈다.$q$, bio_en=$q$Head of the Senate that declared Finland's independence in December 1917, he led the White government in the civil war of 1918 and sought German intervention. He was president from 1931 to 1937.$q$, updated_at=now() WHERE id='pehr-evind-svinhufvud';
UPDATE commulingo_person_sections SET body_ko=$q$제르손 주 농민 가정 출신으로 20세기 초 우크라이나어 문학의 대표적 소설가이자 극작가였고, 우크라이나 사회민주노동당의 지도자로 여러 차례 투옥과 망명을 겪었다. 1917년 6월 중앙라다의 총서기국 의장이 되어 자치 선언과 임시정부와의 교섭을 이끌었고, 11월 우크라이나 인민공화국을 선포한 제3차 우니베르살을 기초했다. 1918년 1월 볼셰비키와의 전쟁 속에서 사임했고, 11월 헤트만에 맞선 디렉토리아의 초대 의장이 되어 12월 키예프를 되찾았다. 소비에트 러시아와의 협상과 노동자·농민 평의회에 기초한 국가를 주장하다 연합국 협력을 원한 페틀류라와 갈라져 1919년 2월 사임하고 국외로 나갔다. 1920년 소비에트 우크라이나로 돌아가 정부 참여를 타진했으나 실질 권한이 없음을 알고 다시 떠났고, 프랑스 남부에서 소설과 일기를 쓰며 살다 1951년 죽었다.$q$, body_en=$q$Born to a peasant family in Kherson province, he was one of the leading novelists and playwrights of early twentieth-century Ukrainian literature and a leader of the Ukrainian Social Democratic Labour Party who was repeatedly imprisoned and exiled. In June 1917 he became chairman of the Central Rada's General Secretariat, leading the declaration of autonomy and the talks with the Provisional Government, and in November drafted the Third Universal proclaiming the Ukrainian People's Republic. He resigned in January 1918 during the war with the Bolsheviks, and in November became first chairman of the Directory against the Hetman, retaking Kyiv in December. Arguing for negotiation with Soviet Russia and a state based on councils of workers and peasants, he broke with Petliura, who wanted Allied cooperation, resigned in February 1919 and went abroad. In 1920 he returned to Soviet Ukraine to explore joining its government, found that the post carried no real power and left again, living in the south of France, writing novels and a diary, until his death in 1951.$q$, updated_at=now() WHERE person_id='volodymyr-vynnychenko' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$우크라이나 사회민주당의 작가로 1917년 중앙라다 총서기국을 이끌고 1918년 디렉토리아 초대 의장으로 키예프를 되찾았다. 소비에트와의 협상을 주장하다 페틀류라와 갈라져 1919년 사임했고 프랑스에서 1951년 죽었다.$q$, bio_en=$q$A Ukrainian Social Democratic writer, he led the Central Rada's General Secretariat in 1917 and retook Kyiv as first chairman of the Directory in 1918. Arguing for talks with the Soviets he broke with Petliura and resigned in 1919, dying in France in 1951.$q$, updated_at=now() WHERE id='volodymyr-vynnychenko';
UPDATE commulingo_person_sections SET body_ko=$q$키예프 대학에서 안토노비치의 제자로 배우고 1894년부터 렘베르크(리비우) 대학의 교수로 일하며 열 권짜리 『우크라이나-루스의 역사』를 썼다. 키예프 루스에서 우크라이나로 이어지는 별개의 역사 계보를 세워 러시아 중심 서술에 맞선 이 저작은 우크라이나 민족운동의 지적 토대가 되었다. 1917년 3월 중앙라다 의장으로 선출되어 자치에서 독립으로 이어지는 우니베르살들을 주도했고, 1918년 4월 29일 라다가 우크라이나 인민공화국 헌법을 채택한 날 독일군의 지원을 받은 헤트만 쿠데타로 권력을 잃었다. 빈에서 망명 생활을 하다 1924년 소비에트 우크라이나로 돌아와 과학 아카데미에서 역사 연구를 이끌었으나, 1931년 체포와 모스크바 이주, 감시 속에서 1934년 키슬로보츠크에서 수술 뒤 죽었다. 그의 학파는 1930년대 숙청으로 해체되었다.$q$, body_en=$q$A pupil of Antonovych at Kyiv University and from 1894 professor at Lemberg (Lviv), he wrote the ten-volume History of Ukraine-Rus, which built a separate historical lineage from Kievan Rus to Ukraine against the Russia-centred account and became the intellectual foundation of the Ukrainian national movement. Elected chairman of the Central Rada in March 1917, he presided over the Universals that led from autonomy to independence, and lost power on 29 April 1918, the day the Rada adopted the constitution of the Ukrainian People's Republic, in the German-backed Hetman coup. After exile in Vienna he returned to Soviet Ukraine in 1924 to lead historical research at the Academy of Sciences, but was arrested in 1931, moved to Moscow and kept under surveillance, and died after surgery at Kislovodsk in 1934. His school was destroyed in the purges of the 1930s.$q$, updated_at=now() WHERE person_id='mykhailo-hrushevsky' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$『우크라이나-루스의 역사』로 우크라이나를 독자적 역사 주체로 서술한 역사학자로 1917~1918년 중앙라다 의장을 맡았다. 1924년 소비에트 우크라이나로 돌아와 감시 속에서 1934년 죽었다.$q$, bio_en=$q$The historian whose History of Ukraine-Rus wrote Ukraine as a distinct historical subject, he chaired the Central Rada in 1917 and 1918. He returned to Soviet Ukraine in 1924 and died under surveillance in 1934.$q$, updated_at=now() WHERE id='mykhailo-hrushevsky';
UPDATE commulingo_person_sections SET body_ko=$q$러시아 제국군의 하급 장교로 1918년 헤트만에 맞선 봉기에 참여해 헤르손 지방의 아타만이 되었고, 디렉토리아의 지휘를 받다가 1919년 2월 부대를 이끌고 소비에트군에 합류했다. 3월 헤르손과 니콜라예프를 점령하고 4월 6일 프랑스군과 그리스군이 철수하는 오데사에 입성해 남부의 연합국 개입을 끝냈다. 그러나 5월 7일 「우니베르살」을 발표하고 곡물 징발과 외지인 관료를 겨눠 소비에트 권력에 반란을 일으켰으며, 그의 부대는 5월 15일부터 17일까지 옐리사베트흐라드에서 유대인 1,500명 이상을 학살하는 등 봉기 중 수십 건의 포그롬을 저질렀다. 봉기가 5월 말 진압된 뒤 마흐노와의 연합을 꾀했으나, 7월 27일 센토베 마을의 회담에서 마흐노 측에 사살되었다. 같은 이름의 사회주의 정치인과 혼동하지 말아야 한다. 출생연도는 자료마다 달라 확정하지 않았다.$q$, body_en=$q$A junior officer of the Russian imperial army, he joined the rising against the Hetman in 1918, became otaman of the Kherson region, served under the Directory and in February 1919 brought his troops over to the Soviets. In March he took Kherson and Mykolaiv and on 6 April entered Odesa as the French and Greek troops evacuated, ending Allied intervention in the south. But on 7 May he issued a 'Universal' and rose against Soviet power, denouncing grain requisitioning and outsider officials, and during the rising his troops committed dozens of pogroms, including the murder of more than 1,500 Jews at Yelysavethrad from 15 to 17 May. After the rising was crushed at the end of May he sought an alliance with Makhno, and on 27 July was shot by Makhno's men at a meeting in the village of Sentove. He should not be confused with the socialist politician of the same name. His year of birth is given differently in the sources and is left unconfirmed.$q$, updated_at=now() WHERE person_id='nykyfor-hryhoriv' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1919년 봄 소비에트군 편에서 오데사를 점령한 우크라이나 아타만으로 5월 반란을 일으켰고, 그의 부대는 옐리사베트흐라드 등에서 유대인을 학살했다. 7월 마흐노 측에 사살되었다.$q$, bio_en=$q$The Ukrainian otaman who took Odesa for the Soviets in the spring of 1919, he rose against them in May and his troops massacred Jews at Yelysavethrad and elsewhere. He was shot by Makhno's men in July.$q$, updated_at=now() WHERE id='nykyfor-hryhoriv';
UPDATE commulingo_person_sections SET body_ko=$q$사레마 섬 출신으로 페테르부르크 대학 법학부에서 볼셰비키 조직에 들어갔고, 1917년 에스토니아 군사혁명위원회에서 10월 혁명을 이끌었으며 1918년 2월 독립 선언 직전 에스토니아 임시정부 각료들을 체포하려 했다. 러시아에서 체카에 근무하며 좌파 사회혁명당 봉기 수사에 참여했고, 1918년 11월 에스토니아 노동 코뮌 시기 에스토니아로 돌아와 지하 조직을 맡았다. 코뮌의 패배 뒤에도 에스토니아 공산당 중앙위원회를 이끌며 신문과 선전을 조직했고 의회 선거에 참여한 합법 노동조직을 배후에서 움직였다. 1922년 5월 3일 탈린에서 체포되어 이틀 뒤 군사법원의 판결로 처형되었고 시신은 바다에 버려졌다. 소비에트 에스토니아 시절 그의 이름은 도시 쿠레사레에 붙었다가 1988년 되돌려졌다.$q$, body_en=$q$Born on the island of Saaremaa, he joined the Bolshevik organization while studying law at St Petersburg University, led the October Revolution in Estonia on its Military Revolutionary Committee in 1917 and tried to arrest the ministers of the Estonian provisional government on the eve of the declaration of independence in February 1918. In Russia he served in the Cheka and took part in the investigation of the Left SR rising, and in November 1918, at the time of the Estonian Workers' Commune, he returned to Estonia to run the underground. After the Commune's defeat he led the Estonian party's central committee, organizing newspapers and propaganda and steering the legal labour organizations that contested parliamentary elections. Arrested in Tallinn on 3 May 1922, he was executed two days later by sentence of a military court and his body was thrown into the sea. Under Soviet rule the town of Kuressaare bore his name until 1988.$q$, updated_at=now() WHERE person_id='viktor-kingissepp' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1917년 에스토니아의 10월 혁명을 이끈 볼셰비키로 독립 공화국에서 지하 공산당을 지도하다 1922년 탈린에서 체포되어 처형되었다.$q$, bio_en=$q$The Bolshevik who led the October Revolution in Estonia in 1917, he directed the underground communist party in the independent republic until his arrest and execution in Tallinn in 1922.$q$, updated_at=now() WHERE id='viktor-kingissepp';
UPDATE commulingo_person_sections SET body_ko=$q$페테르부르크 대학에서 법을 공부한 뒤 나르바에서 사회민주주의 언론을 이끌었고, 1917년 에스토니아 소비에트 집행위원회 의장으로 10월 혁명 뒤 에스토니아의 볼셰비키 권력을 대표했다. 1918년 11월 29일 붉은 군대가 나르바를 점령하자 에스토니아 노동 코뮌의 수반으로 선포되어 두 달 남짓 에스토니아 동부를 통치했고, 코뮌 시기 인질 처형과 징발은 이후 독립 공화국의 반공 선전에 오래 쓰였다. 1919년 코뮌이 해산된 뒤 붉은 군대의 정치위원으로 일했고, 1921년부터 에스토니아 지하 공산당을 지도해 1924년 12월 1일 탈린 봉기를 조직했으나 몇 시간 만에 실패했다. 소련으로 돌아가 코민테른 집행위원회와 항공 산업에서 일했으며, 1937년 12월 체포되어 심문 중 구타로 죽었다.$q$, body_en=$q$After studying law at St Petersburg University he ran the social democratic press in Narva, and in 1917, as chairman of the executive committee of Estonia's soviets, represented Bolshevik power in Estonia after the October Revolution. When the Red Army took Narva on 29 November 1918 he was proclaimed head of the Estonian Workers' Commune and governed eastern Estonia for a little over two months; the Commune's executions of hostages and requisitions were long used in the independent republic's anti-communist propaganda. After the Commune dissolved in 1919 he served as a Red Army political commissar, and from 1921 directed the underground Estonian party, organizing the Tallinn rising of 1 December 1924, which failed within hours. Back in the Soviet Union he worked for the Comintern executive and the aviation industry, was arrested in December 1937 and died under beating during interrogation.$q$, updated_at=now() WHERE person_id='jaan-anvelt' AND slug='independence-wars';
UPDATE commulingo_people SET bio_ko=$q$1918년 11월 나르바에 선포된 에스토니아 노동 코뮌의 수반으로 두 달 남짓 에스토니아 동부를 통치했고 1924년 탈린 봉기를 조직했다. 1937년 체포되어 심문 중 구타로 죽었다.$q$, bio_en=$q$Head of the Estonian Workers' Commune proclaimed at Narva in November 1918, he governed eastern Estonia for two months and organized the Tallinn rising of 1924. Arrested in 1937, he died under beating during interrogation.$q$, updated_at=now() WHERE id='jaan-anvelt';
-- Name-order audit: the particle belongs in the family-name part (cf. rudiger-von-der-goltz).
UPDATE commulingo_people SET family_name_ko='폰 만토이펠-쇠게', family_name_en='von Manteuffel-Szoege', updated_at=now() WHERE id='hans-von-manteuffel-szoege';
COMMIT;

BEGIN;
-- civil-war notes for the 20 borderland people still held the first short bios; reuse the event-specific notes.
UPDATE commulingo_history_event_people SET note_ko=$q$1918년 12월 소비에트 리투아니아 정부의 수반이 되어 1919년 1월 빌뉴스에 들어가고 2월 리트벨을 이끌었으나, 4월 폴란드군의 빌뉴스 점령 뒤 러시아로 물러났다.$q$, note_en=$q$Head of the Soviet government of Lithuania from December 1918, he entered Vilnius in January 1919 and led Litbel from February, withdrawing to Russia after the Poles took Vilnius in April.$q$ WHERE event_id='civil-war' AND person_id='vincas-kapsukas';
UPDATE commulingo_history_event_people SET note_ko=$q$1918년 11월 임시정부 수반으로 권력을 넘겨받아 붉은 군대가 탈린 앞까지 온 첫 겨울에 정부를 지켰고, 라이도네르의 임명과 강제 징집, 영국 함대의 지원을 관철했다.$q$, note_en=$q$Took over as head of the provisional government in November 1918 and held it together in the first winter with the Red Army before Tallinn, pushing through Laidoner's appointment, conscription and British naval support.$q$ WHERE event_id='civil-war' AND person_id='konstantin-pats';
UPDATE commulingo_history_event_people SET note_ko=$q$1918년 12월 23일 총사령관에 임명되어 1919년 1월 반격과 6월 체시스 전투를 지휘했고, 유데니치와는 조건부로 협력하되 페트로그라드 공격에는 가담하지 않았다.$q$, note_en=$q$Appointed commander-in-chief on 23 December 1918, he directed the counteroffensive of January 1919 and the battle of Cēsis in June, cooperating conditionally with Yudenich but taking no part in the attack on Petrograd.$q$ WHERE event_id='civil-war' AND person_id='johan-laidoner';
UPDATE commulingo_history_event_people SET note_ko=$q$1919년 11월 총리가 되어 타르투 강화 협상을 뒷받침했고, 1920년 2월 2일 조약이 그의 정부 아래 체결되었다.$q$, note_en=$q$Became prime minister in November 1919 and backed the Tartu peace talks; the treaty of 2 February 1920 was signed under his government.$q$ WHERE event_id='civil-war' AND person_id='jaan-tonisson';
UPDATE commulingo_history_event_people SET note_ko=$q$1918년 11월부터 임시정부 총리로 리예파야로 밀려나고 배 위로 피신하는 위기를 넘겨 1919년 7월 리가로 돌아왔고, 베르몬트군을 격퇴한 뒤 1920년 리가 강화와 토지개혁을 이끌었다.$q$, note_en=$q$Prime minister of the provisional government from November 1918, he survived the retreat to Liepāja and refuge aboard ship, returned to Riga in July 1919, repelled Bermondt's army and led the Riga peace and land reform of 1920.$q$ WHERE event_id='civil-war' AND person_id='karlis-ulmanis';
UPDATE commulingo_history_event_people SET note_ko=$q$1919년 4월 리예파야 쿠데타 뒤 5월 10일 폰 데어 골츠가 뒷받침한 친독 정부의 수반이 되었고, 6월 체시스 전투 뒤 정권이 무너져 독일로 피했다.$q$, note_en=$q$Became head of the pro-German government backed by von der Goltz on 10 May 1919 after the Liepāja coup, and fled to Germany when the regime collapsed after Cēsis in June.$q$ WHERE event_id='civil-war' AND person_id='andrievs-niedra';
UPDATE commulingo_history_event_people SET note_ko=$q$초대 외무장관으로 연합국 사절단을 움직여 독일군 철수를 이끌어 냈고, 1920년 8월 리가 강화와 1921년 연합국의 법적 승인을 얻어 냈다.$q$, note_en=$q$As first foreign minister he worked the Allied missions to secure the German withdrawal and obtained the Riga peace of August 1920 and de jure recognition from the Allies in 1921.$q$ WHERE event_id='civil-war' AND person_id='zigfrids-meierovics';
UPDATE commulingo_history_event_people SET note_ko=$q$1919년 2월 리예파야에서 독일군과 향토방위군을 지휘해 5월 리가를 탈환했으나 라트비아 정부를 장애물로 여겨 쿠데타를 뒷받침했고, 체시스 패배 뒤 10월 소환되었다.$q$, note_en=$q$Commanded the German troops and the Landeswehr from Liepāja from February 1919 and retook Riga in May, but treated the Latvian government as an obstacle and backed the coup; recalled in October after the defeat at Cēsis.$q$ WHERE event_id='civil-war' AND person_id='rudiger-von-der-goltz';
UPDATE commulingo_history_event_people SET note_ko=$q$1919년 10월 8일 철수를 거부한 독일 병력으로 이루어진 서러시아 의용군을 이끌고 리가를 공격했다가 11월 11일 격퇴되었고 12월 독일로 물러났다.$q$, note_en=$q$Attacked Riga on 8 October 1919 with the West Russian Volunteer Army of German troops who had refused to leave, was repelled on 11 November and withdrew to Germany in December.$q$ WHERE event_id='civil-war' AND person_id='pavel-bermondt-avalov';
UPDATE commulingo_history_event_people SET note_ko=$q$1919년 4월 초대 대통령에 선출되어 붉은 군대, 베르몬트군, 폴란드군과 싸우는 첫 정부들을 이끌었다.$q$, note_en=$q$Elected first president in April 1919, he led the first governments that fought the Red Army, Bermondt's troops and the Polish army.$q$ WHERE event_id='civil-war' AND person_id='antanas-smetona';
UPDATE commulingo_history_event_people SET note_ko=$q$1918년 11월 초대 총리로 군대 창설을 늦추었다가 사퇴했고, 이후 외무장관으로 파리와 국제연맹에서 빌뉴스 문제를 다투었다.$q$, note_en=$q$First prime minister from November 1918, he delayed creating an army and resigned, then as foreign minister fought the Vilnius question in Paris and at the League of Nations.$q$ WHERE event_id='civil-war' AND person_id='augustinas-voldemaras';
UPDATE commulingo_history_event_people SET note_ko=$q$소비에트 리투아니아와 리트벨 정부의 내무 인민위원으로 1918~1919년 소비에트 국가 건설에 참여했다.$q$, note_en=$q$Commissar for internal affairs in the Soviet Lithuanian and Litbel governments, taking part in Soviet state-building in 1918 and 1919.$q$ WHERE event_id='civil-war' AND person_id='zigmas-angarietis';
UPDATE commulingo_history_event_people SET note_ko=$q$1920년 10월 9일 피우수트스키와 협의한 「항명」으로 빌뉴스를 점령하고 중부 리투아니아를 세워 1922년 폴란드에 편입시켰다.$q$, note_en=$q$Seized Vilnius on 9 October 1920 in a 'mutiny' agreed with Piłsudski and set up Central Lithuania, incorporated into Poland in 1922.$q$ WHERE event_id='civil-war' AND person_id='lucjan-zeligowski';
UPDATE commulingo_history_event_people SET note_ko=$q$1919년 5월 백군 북부군단의 일원으로 프스코프를 점령했고, 유데니치와 갈라져 에스토니아 편에 섰다가 1920년 부대와 함께 폴란드로 옮겼다.$q$, note_en=$q$Took Pskov in May 1919 with the White Northern Corps, broke with Yudenich to side with the Estonians, and moved with his troops to Poland in 1920.$q$ WHERE event_id='civil-war' AND person_id='stanislaw-bulak-balachowicz';
UPDATE commulingo_history_event_people SET note_ko=$q$백색정부의 수반으로 만네르헤임의 반대를 무릅쓰고 독일에 군사 개입을 요청했고, 1918년 3월 7일 독일과 조약을 맺었다.$q$, note_en=$q$As head of the White government he asked Germany for military intervention over Mannerheim's objections and concluded treaties with Germany on 7 March 1918.$q$ WHERE event_id='civil-war' AND person_id='pehr-evind-svinhufvud';
UPDATE commulingo_history_event_people SET note_ko=$q$중앙라다 총서기국 의장으로 우크라이나의 별도 강화 노선을 승인했고, 소비에트군의 키예프 점령 직후인 1918년 1월 말 사임했다.$q$, note_en=$q$As chairman of the Rada's General Secretariat he approved Ukraine's separate peace and resigned at the end of January 1918, just as Soviet troops took Kyiv.$q$ WHERE event_id='civil-war' AND person_id='volodymyr-vynnychenko';
UPDATE commulingo_history_event_people SET note_ko=$q$중앙라다 의장으로 브레스트의 별도 강화와 독일군의 진입을 받아들였고, 1918년 4월 29일 헤트만 쿠데타로 권력을 잃었다.$q$, note_en=$q$As chairman of the Central Rada he accepted the separate peace at Brest and the entry of German troops, and lost power in the Hetman coup of 29 April 1918.$q$ WHERE event_id='civil-war' AND person_id='mykhailo-hrushevsky';
UPDATE commulingo_history_event_people SET note_ko=$q$1919년 4월 소비에트군 편에서 오데사를 점령한 뒤 5월 반란을 일으켰고, 그의 부대는 옐리사베트흐라드에서 유대인 1,500명 이상을 학살했다. 7월 마흐노 측에 사살되었다.$q$, note_en=$q$Took Odesa for the Soviets in April 1919, rose against them in May, and his troops massacred more than 1,500 Jews at Yelysavethrad; he was shot by Makhno's men in July.$q$ WHERE event_id='civil-war' AND person_id='nykyfor-hryhoriv';
UPDATE commulingo_history_event_people SET note_ko=$q$노동 코뮌 시기부터 에스토니아 공산주의 지하 조직을 이끌었고, 1922년 5월 탈린에서 체포되어 이틀 뒤 처형되었다.$q$, note_en=$q$Led the Estonian communist underground from the time of the Workers' Commune, and was arrested in Tallinn in May 1922 and executed two days later.$q$ WHERE event_id='civil-war' AND person_id='viktor-kingissepp';
UPDATE commulingo_history_event_people SET note_ko=$q$1918년 11월 29일 나르바에서 선포된 에스토니아 노동 코뮌의 수반으로 두 달 남짓 에스토니아 동부를 통치했고, 1919년 6월 코뮌 해산 때까지 이끌었다.$q$, note_en=$q$Head of the Estonian Workers' Commune proclaimed at Narva on 29 November 1918, he governed eastern Estonia for a little over two months and led the Commune until it dissolved in June 1919.$q$ WHERE event_id='civil-war' AND person_id='jaan-anvelt';
UPDATE commulingo_history_event_people SET note_ko=$q$1920년 10월 7일 수바우키 협정이 빌뉴스를 리투아니아 쪽에 남기자, 피우수트스키와 협의한 「항명」으로 10월 9일 빌뉴스를 점령해 중부 리투아니아를 세웠다.$q$, note_en=$q$When the Suwałki Agreement of 7 October 1920 left Vilnius on the Lithuanian side, he seized the city on 9 October in a 'mutiny' agreed with Piłsudski and set up Central Lithuania.$q$ WHERE event_id='soviet-polish-war' AND person_id='lucjan-zeligowski';
UPDATE commulingo_history_event_people SET note_ko=$q$1920년 폴란드군 아래에서 싸운 뒤 10월 휴전 뒤에도 벨로루시 인민공화국을 내걸고 모지르로 독자 원정을 벌였으나 11월 패퇴했다. 부대의 반유대인 폭력이 기록되어 있다.$q$, note_en=$q$After fighting under Polish command in 1920 he marched on Mozyr under the banner of a Belarusian People's Republic even after the October armistice, and was beaten in November; his troops' anti-Jewish violence is on record.$q$ WHERE event_id='soviet-polish-war' AND person_id='stanislaw-bulak-balachowicz';
COMMIT;
